use graph::Graph;

#[test]
fn test_neighbors() {
    let mut g = Graph::new();
    g.add_edge(1, 2);
    g.add_edge(1, 3);
    let mut nbrs = g.neighbors(1).to_vec();
    nbrs.sort();
    assert_eq!(nbrs, vec![2, 3]);
    assert_eq!(g.neighbors(99).len(), 0);
}

#[test]
fn test_bfs_order_visits_all() {
    let mut g = Graph::new();
    g.add_edge(0, 1);
    g.add_edge(0, 2);
    g.add_edge(1, 3);
    let order = g.bfs_order(0);
    assert_eq!(order[0], 0);
    assert!(order.contains(&1));
    assert!(order.contains(&2));
    assert!(order.contains(&3));
    assert_eq!(order.len(), 4);
}

#[test]
fn test_has_path_direct() {
    let mut g = Graph::new();
    g.add_edge(1, 2);
    assert!(g.has_path(1, 2));
}

#[test]
fn test_has_path_indirect_and_directed() {
    let mut g = Graph::new();
    g.add_edge(1, 2);
    g.add_edge(2, 3);
    assert!(g.has_path(1, 3));
    assert!(!g.has_path(3, 1)); // directed — no reverse edge
}

#[test]
fn test_has_path_self() {
    let g = Graph::new();
    assert!(g.has_path(5, 5));
}

